function solve([s]) {
  let depth = 0;
  let maxDepth = 0;
  let pairs = 0;
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '[') {
      depth++;
      if (depth > maxDepth) maxDepth = depth;
    } else if (s[i] === ']') {
      if (depth > 0) {
        depth--;
        pairs++;
      }
    }
  }
  return pairs >= 2 && maxDepth >= 2;
}

