function solve([grid, k]) {
  const n = grid.length;
  const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
  const best = new Array(k).fill(Infinity);
  const visited = new Array(k).fill(null).map(() => new Set());
  const queue = [];
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      queue.push([r, c, 0, [grid[r][c]]]);
    }
  }
  let head = 0;
  while (head < queue.length) {
    const [r, c, step, path] = queue[head++];
    if (step >= k) continue;
    if (path[step] > best[step]) continue;
    if (path[step] < best[step]) {
      best[step] = path[step];
      visited[step].clear();
    }
    const key = r * n + c;
    if (visited[step].has(key)) continue;
    visited[step].add(key);
    if (step === k - 1) continue;
    for (const [dr, dc] of dirs) {
      const nr = r + dr;
      const nc = c + dc;
      if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
        const np = path.concat([grid[nr][nc]]);
        if (grid[nr][nc] <= best[step + 1]) {
          queue.push([nr, nc, step + 1, np]);
        }
      }
    }
  }
  return best;
}

